const hostNode = (type, props = {}) => ({ type, props, children: [] })
const nodeOps = {
  createElement: (tag, _ns, _p, props) => hostNode(tag, { ...props }),
  createText: (t) => ({ text: t }),
  createComment: (t) => ({ comment: t }),
  parentNode: (n) => n.parent || null,
  nextSibling: (n) => {
    const p = n.parent; if (!p) return null
    return p.children[p.children.indexOf(n) + 1] || null
  },
  insert(child, parent, anchor = null) {
    if (child.parent) child.parent.children.splice(child.parent.children.indexOf(child), 1)
    child.parent = parent
    const i = anchor ? parent.children.indexOf(anchor) : -1
    if (i > -1) parent.children.splice(i, 0, child)
    else parent.children.push(child)
  },
  remove: (child) => {
    const p = child.parent; if (!p) return
    const i = p.children.indexOf(child)
    if (i > -1) { p.children.splice(i, 1); child.parent = null }
  },
  patchProp: (el, key, prev, next) => { el.props[key] = next },
}
// 迷你 mount：vnode={type,props,children|text}
function mount(vnode, parent) {
  const host = vnode.text != null ? nodeOps.createText(vnode.text)
    : nodeOps.createElement(vnode.type, null, null, vnode.props || {})
  for (const c of vnode.children || []) if (c) mount(c, host)
  nodeOps.insert(host, parent)
  return host
}
function createJsonApp(rootVnode) {
  const root = hostNode('#root')
  return { mount: () => mount(rootVnode, root), toJSON: () => root }
}
